const crypto = require('crypto');
const secret = process.env.RR_CRM_CREDENTIAL_SECRET;
const callbackUrl = process.env.RR_CRM_CALLBACK_URL;
const credentialId = process.env.RR_CRM_CREDENTIAL_ID;
if (!secret || !callbackUrl || !credentialId) throw new Error('RR_CRM_* environment is incomplete');
const allowed = new Set(['accepted','dismissed','snoozed','resumed','contacted','replied','meeting','meeting_completed','meeting_cancelled','meeting_no_show','proposal','won','lost']);
if (!allowed.has($json.eventType)) throw new Error('Unsupported outcome event');
if (!/^[A-Za-z0-9._:-]{1,120}$/.test($json.eventId)) throw new Error('Stable provider eventId is required');
const body = { opportunityReference: $json.opportunityReference, eventType: $json.eventType, occurredAt: $json.occurredAt };
for (const key of ['reasonCode','reasonNote','channel','contactPathType','snoozeDays','snoozedUntil','valueMinor','currency']) if ($json[key] !== undefined) body[key] = $json[key];
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const key = crypto.createHash('sha256').update(secret, 'utf8').digest();
const signature = 'v1=' + crypto.createHmac('sha256', key).update(`${timestamp}\n${$json.eventId}\n${rawBody}`, 'utf8').digest('hex');
return [{ json: { callbackUrl, rawBody, headers: { 'X-RR-Credential-Id': credentialId, 'X-RR-Webhook-Timestamp': timestamp, 'X-RR-Webhook-Id': $json.eventId, 'X-RR-Signature': signature } } }];
